"""Credential Manager and Vault container parsers.

Credential Manager files (``Credentials\\<hash>``) and Vault policy files
(``Policy.vpol``) wrap one or more DPAPI blobs inside a container header, so they are
not bare blobs: the blob begins four bytes before the provider GUID. Vault credential
files (``*.vcrd``) are not DPAPI-protected at all; their attributes are AES-encrypted
under the keys recovered from the matching ``Policy.vpol``.
"""
import struct

from .blob import DpapiBlob, PROVIDER_GUID_LE


def _u32(buf, off):
    return struct.unpack('<L', buf[off:off + 4])[0]


def _blob_offsets(data):
    """Offsets of every DPAPI blob in a container (each starts 4 bytes before a GUID)."""
    offsets = []
    start = 0
    while True:
        pos = data.find(PROVIDER_GUID_LE, start)
        if pos < 4:
            break
        offsets.append(pos - 4)
        start = pos + 16
    return offsets


class CredentialFile:
    """A Credential Manager file: one wrapped DPAPI blob."""

    def __init__(self, data):
        offsets = _blob_offsets(data)
        if not offsets:
            raise ValueError('no DPAPI blob in credential file')
        self.blob = DpapiBlob(data[offsets[0]:])
        self.cleartext = None

    def decrypt(self, master_key, entropy=None):
        self.cleartext = self.blob.decrypt(master_key, entropy=entropy)
        return self.cleartext

    def fields(self):
        """Best-effort CREDENTIAL fields from the decrypted cleartext.

        Returns a dict with the last-written time and the sequence of UTF-16 strings
        (target, alias, comment, username ...) the structure carries. The trailing
        secret is returned as raw bytes under ``secret``.
        """
        if self.cleartext is None:
            return None
        buf = self.cleartext
        info = {}
        if len(buf) >= 32:
            info['last_written_filetime'] = struct.unpack('<Q', buf[24:32])[0]
        strings = []
        o = 36
        # The structure is a run of length-prefixed UTF-16 strings; walk them defensively.
        while o + 4 <= len(buf):
            slen = _u32(buf, o)
            o += 4
            if slen == 0 or o + slen > len(buf) or slen > 2048 or slen % 2:
                break
            strings.append(buf[o:o + slen].decode('utf-16-le', 'replace').rstrip('\x00'))
            o += slen
        info['strings'] = strings
        info['secret'] = buf[o:]
        return info


def _bcrypt_key_bytes(cleartext):
    """Extract the AES key bytes from a decrypted VAULT_POL key structure.

    The decrypted blob holds a small header, a GUID and a key container whose last
    field is the raw AES key. The key container is located by its ``size`` prefix.
    """
    # Layout: DWORD keyCount/size; GUID(16); DWORD; DWORD; then key container:
    #   DWORD cbKey; ... 'KSSM'/bcrypt header ... key bytes at the tail.
    # The reliable anchor is the final DWORD-sized length that leaves exactly that
    # many bytes to the end; fall back to known AES sizes.
    for key_len in (32, 24, 16):
        tail = cleartext[-key_len:]
        if len(tail) == key_len:
            # verify there is a length DWORD equal to key_len just before the key block
            marker = cleartext.rfind(struct.pack('<L', key_len))
            if marker != -1 and marker + 4 + key_len <= len(cleartext):
                cand = cleartext[marker + 4:marker + 4 + key_len]
                if len(cand) == key_len:
                    return cand
    return None


class VaultPolicy:
    """A Vault ``Policy.vpol`` file: the AES keys that protect the matching ``*.vcrd``."""

    def __init__(self, data):
        self.data = data
        self.blobs = [DpapiBlob(data[o:]) for o in _blob_offsets(data)]
        self.cleartexts = []
        self.aes_keys = []

    def decrypt(self, master_key, entropy=None):
        """Decrypt every wrapped blob with one master key (each blob names its GUID)."""
        return self._decrypt(lambda _blob: master_key, entropy)

    def decrypt_with_pool(self, pool, entropy=None):
        """Decrypt every wrapped blob, resolving each blob's master key from ``pool``."""
        return self._decrypt(lambda blob: pool.get_key(blob.mk_guid), entropy)

    def _decrypt(self, key_for, entropy):
        self.cleartexts = []
        self.aes_keys = []
        for blob in self.blobs:
            key = key_for(blob)
            if key is None:
                continue
            clear = blob.decrypt(key, entropy=entropy)
            if clear is None:
                continue
            self.cleartexts.append(clear)
            aes_key = _bcrypt_key_bytes(clear)
            if aes_key:
                self.aes_keys.append(aes_key)
        return self.cleartexts

    def key_material(self):
        """The concatenated decrypted key cleartexts (a stable fingerprint target)."""
        return b''.join(self.cleartexts)


class VaultCredential:
    """A Vault credential record (``*.vcrd``): outer structure and attribute map.

    The attributes are AES-encrypted under the keys from the matching ``Policy.vpol``.
    This parser exposes the record's identity (schema GUID, friendly name, last-written
    time) and the raw attribute blobs. Attribute decryption is a user-context concern
    (the vaults that carry credential records are user vaults, unlocked by a user master
    key) and is left to the credential-gated phase, where a real target and a recovered
    AES key make it verifiable; the SYSTEM vaults seen here hold only policy and schema
    files, no credential records.
    """

    def __init__(self, data):
        self.data = data
        self.schema_guid = DpapiBlob._guid(data[0:16])
        self.last_written_filetime = struct.unpack('<Q', data[20:28])[0]
        name_len = _u32(data, 36)
        self.friendly_name = data[40:40 + name_len].decode('utf-16-le', 'replace').rstrip('\x00')
        o = 40 + name_len
        maps_len = _u32(data, o)
        o += 4
        entries = []
        for _ in range(maps_len // 12):
            attr_id, offset, _unk = struct.unpack('<LLL', data[o:o + 12])
            entries.append((attr_id, offset))
            o += 12
        self.attributes = []
        for idx, (attr_id, offset) in enumerate(entries):
            end = entries[idx + 1][1] if idx + 1 < len(entries) else len(data)
            self.attributes.append({'id': attr_id, 'offset': offset,
                                    'raw': data[offset:end]})
